import{_ as n,o,c as t,an as a}from"./chunks/framework.vGf3s8kh.js";const g=JSON.parse('{"title":"Oceananigans.jl — Agent Rules","description":"","frontmatter":{},"headers":[],"relativePath":"developer_docs/AGENTS.md","filePath":"developer_docs/AGENTS.md","lastUpdated":null}'),s={name:"developer_docs/AGENTS.md"};function i(l,e,r,c,d,p){return o(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="Oceananigans.jl-—-Agent-Rules" tabindex="-1">Oceananigans.jl — Agent Rules <a class="header-anchor" href="#Oceananigans.jl-—-Agent-Rules" aria-label="Permalink to &quot;Oceananigans.jl — Agent Rules {#Oceananigans.jl-—-Agent-Rules}&quot;">​</a></h1><h2 id="Project-Overview" tabindex="-1">Project Overview <a class="header-anchor" href="#Project-Overview" aria-label="Permalink to &quot;Project Overview {#Project-Overview}&quot;">​</a></h2><p>Oceananigans.jl is a Julia package for fast, friendly, flexible, ocean-flavored fluid dynamics on CPUs and GPUs. It solves the incompressible (Boussinesq) Navier-Stokes equations with models including: nonhydrostatic (with free surfaces), hydrostatic free-surface, and shallow water — on RectilinearGrid, LatitudeLongitudeGrid, CubedSphereGrid, and ImmersedBoundaryGrid.</p><h2 id="Language-and-Environment" tabindex="-1">Language &amp; Environment <a class="header-anchor" href="#Language-and-Environment" aria-label="Permalink to &quot;Language &amp; Environment {#Language-and-Environment}&quot;">​</a></h2><ul><li><p><strong>Julia 1.10+</strong> | CPU and GPU (CUDA, AMD, Metal, OneAPI)</p></li><li><p><strong>Key packages</strong>: KernelAbstractions.jl, CUDA.jl, Enzyme.jl, Reactant.jl</p></li><li><p><strong>Style</strong>: ExplicitImports.jl for source code; <code>using Oceananigans</code> for examples/tests</p></li></ul><h2 id="Critical-Rules" tabindex="-1">Critical Rules <a class="header-anchor" href="#Critical-Rules" aria-label="Permalink to &quot;Critical Rules {#Critical-Rules}&quot;">​</a></h2><h3 id="Kernel-Functions-GPU-compatibility" tabindex="-1">Kernel Functions (GPU compatibility) <a class="header-anchor" href="#Kernel-Functions-GPU-compatibility" aria-label="Permalink to &quot;Kernel Functions (GPU compatibility) {#Kernel-Functions-GPU-compatibility}&quot;">​</a></h3><ul><li><p>Use <code>@kernel</code> / <code>@index</code> (KernelAbstractions.jl)</p></li><li><p>Kernels must be <strong>type-stable</strong> and <strong>allocation-free</strong></p></li><li><p>Use <code>ifelse</code> — never short-circuiting <code>if</code>/<code>else</code> in kernels</p></li><li><p>No error messages, no Models inside kernels</p></li><li><p>Mark functions called inside kernels with <code>@inline</code></p></li><li><p><strong>Never loop over grid points outside kernels</strong> — use <code>launch!</code></p></li></ul><h3 id="Type-Stability-and-Memory" tabindex="-1">Type Stability &amp; Memory <a class="header-anchor" href="#Type-Stability-and-Memory" aria-label="Permalink to &quot;Type Stability &amp; Memory {#Type-Stability-and-Memory}&quot;">​</a></h3><ul><li><p>All structs must be concretely typed</p></li><li><p>Type annotations are for <strong>dispatch</strong>, not documentation</p></li><li><p>Minimize allocation; favor inline computation</p></li><li><p><strong>Never hardcode Float64</strong>: no literal <code>0.0</code> or <code>1.0</code> in kernels or constructors. Use <code>zero(grid)</code>, <code>one(grid)</code>, <code>convert(FT, 1//2)</code>, or rational literals</p></li></ul><h3 id="Imports" tabindex="-1">Imports <a class="header-anchor" href="#Imports" aria-label="Permalink to &quot;Imports {#Imports}&quot;">​</a></h3><ul><li><p>Source code: explicit imports (checked by tests)</p></li><li><p>Examples/docs: rely on <code>using Oceananigans</code>; never explicitly import exported names</p></li></ul><h3 id="Docstrings" tabindex="-1">Docstrings <a class="header-anchor" href="#Docstrings" aria-label="Permalink to &quot;Docstrings {#Docstrings}&quot;">​</a></h3><ul><li><p>Use DocStringExtensions.jl with <code>$(TYPEDSIGNATURES)</code> when the signature does not include default values for args and/or kwargs.</p></li><li><p><strong>ALWAYS <code>jldoctest</code> blocks, NEVER plain <code>julia</code> blocks</strong> — doctests are tested; plain blocks rot</p></li><li><p>Include <code># output</code> with verifiable output; prefer <code>show</code> methods over boolean comparisons</p></li><li><p>Use unicode for math (<code>Δt</code>, <code>η</code>, <code>ρ</code>), not LaTeX — LaTeX doesn&#39;t render in the REPL</p></li></ul><h3 id="Model-Constructors" tabindex="-1">Model Constructors <a class="header-anchor" href="#Model-Constructors" aria-label="Permalink to &quot;Model Constructors {#Model-Constructors}&quot;">​</a></h3><ul><li><p><code>grid</code> is positional: <code>NonhydrostaticModel(grid; closure=nothing)</code></p></li><li><p><code>ShallowWaterModel(grid, gravitational_acceleration; ...)</code> — both positional</p></li><li><p>Omit semicolon when there are no keyword arguments: <code>NonhydrostaticModel(grid)</code> not <code>NonhydrostaticModel(grid;)</code></p></li></ul><h2 id="Naming-Conventions" tabindex="-1">Naming Conventions <a class="header-anchor" href="#Naming-Conventions" aria-label="Permalink to &quot;Naming Conventions {#Naming-Conventions}&quot;">​</a></h2><ul><li><p><strong>Files</strong>: snake_case matching the type they define — <code>nonhydrostatic_model.jl</code></p></li><li><p><strong>Types/Constructors</strong>: PascalCase <strong>only for true constructors</strong> — <code>NonhydrostaticModel</code></p></li><li><p><strong>Functions</strong>: snake_case — <code>time_step!</code>; functions that return values are never PascalCase</p></li><li><p><strong>Kernels</strong>: may prefix with underscore — <code>_compute_tendency_kernel</code></p></li><li><p><strong>Variables</strong>: English long name or readable unicode math notation — never mix abbreviated and full forms (e.g., <code>cond</code> vs <code>condition</code>) to imply a difference; be specific</p></li></ul><h2 id="Module-Structure" tabindex="-1">Module Structure <a class="header-anchor" href="#Module-Structure" aria-label="Permalink to &quot;Module Structure {#Module-Structure}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>├── Oceananigans.jl            # Main module, exports</span></span>
<span class="line"><span>├── Architectures.jl           # CPU/GPU architecture abstractions</span></span>
<span class="line"><span>├── Grids/                     # Grid types and constructors</span></span>
<span class="line"><span>├── Fields/                    # Field types and operations</span></span>
<span class="line"><span>├── Operators/                 # Finite difference operators</span></span>
<span class="line"><span>├── BoundaryConditions/        # Boundary condition types</span></span>
<span class="line"><span>├── Models/                    # Model implementations</span></span>
<span class="line"><span>│   ├── NonhydrostaticModels/</span></span>
<span class="line"><span>│   ├── HydrostaticFreeSurfaceModels/</span></span>
<span class="line"><span>│   ├── ShallowWaterModels/</span></span>
<span class="line"><span>│   └── LagrangianParticleTracking/</span></span>
<span class="line"><span>├── TimeSteppers/              # Time stepping schemes</span></span>
<span class="line"><span>├── Solvers/                   # Poisson and tridiagonal solvers</span></span>
<span class="line"><span>├── TurbulenceClosures/        # LES and eddy viscosity models</span></span>
<span class="line"><span>├── Advection/                 # Advection schemes</span></span>
<span class="line"><span>├── BuoyancyFormulations/      # Buoyancy models</span></span>
<span class="line"><span>├── OutputWriters/             # File I/O</span></span>
<span class="line"><span>├── Simulations/               # High-level simulation interface</span></span>
<span class="line"><span>└── Utils/                     # Utilities and helpers</span></span></code></pre></div><h2 id="Common-Pitfalls" tabindex="-1">Common Pitfalls <a class="header-anchor" href="#Common-Pitfalls" aria-label="Permalink to &quot;Common Pitfalls {#Common-Pitfalls}&quot;">​</a></h2><ol><li><p><strong>Type instability</strong> in kernels ruins GPU performance</p></li><li><p><strong>Overconstraining types</strong>: use annotations for dispatch, not documentation</p></li><li><p><strong>Missing imports</strong>: tests will catch this — add to <code>using</code> statements</p></li><li><p><strong>Plain <code>julia</code> blocks in docstrings</strong>: always use <code>jldoctest</code></p></li><li><p><strong>Subtle bugs from missing method imports</strong>, especially in extensions</p></li><li><p><strong>Expecting unexported names</strong>: consider exporting them rather than changing user scripts</p></li><li><p><strong>Extending <code>getproperty</code> to fix undefined property bugs</strong>: fix on the caller side instead</p></li><li><p><strong>&quot;Type is not callable&quot; errors</strong>: variable name shadows a function — rename or qualify</p></li><li><p><strong>Quick fixes that break correctness</strong>: if a test fails after a change, revisit the original edit</p></li><li><p><strong>Commented-out code</strong>: delete it. Git is the journal — don&#39;t leave commented code, debugging artifacts, or stale copy-paste remnants</p></li><li><p><strong>2D indexing on fields</strong>: always use 3D indexing (<code>field[i, j, k]</code>). 2D indexing works by coincidence on some fields but is unsupported and will break</p></li><li><p><strong>Hardcoded Float64</strong>: never use <code>0.0</code>, <code>1.0</code> in kernels or constructors; use <code>zero(grid)</code> etc.</p></li><li><p><strong>Scope creep in PRs</strong>: keep changes focused on a single concern. Unrelated cleanup goes in a separate PR</p></li><li><p><strong>Modifying Project.toml dependencies</strong>: never add, remove, or change <code>[deps]</code> or <code>[weakdeps]</code> in the root <code>Project.toml</code> unless the task absolutely requires it. Dependency changes have wide-reaching consequences — they affect CI, load time, and downstream compatibility. Only touch <code>[compat]</code> bounds when explicitly asked.</p></li></ol><h2 id="Git-Workflow" tabindex="-1">Git Workflow <a class="header-anchor" href="#Git-Workflow" aria-label="Permalink to &quot;Git Workflow {#Git-Workflow}&quot;">​</a></h2><p>Follow <a href="https://github.com/SciML/ColPrac" target="_blank" rel="noreferrer">ColPrac</a>. Feature branches, descriptive commits, update tests and docs with code changes, check CI before merging.</p><h2 id="Design-Principles" tabindex="-1">Design Principles <a class="header-anchor" href="#Design-Principles" aria-label="Permalink to &quot;Design Principles {#Design-Principles}&quot;">​</a></h2><ul><li><p><strong>Dispatch over conditionals</strong>: use Julia&#39;s type system and multiple dispatch instead of <code>if</code>/<code>else</code> branching. Backend-specific code goes in <code>ext/</code> extensions, not <code>if</code> branches in <code>src/</code></p></li><li><p><strong>Use <code>on_architecture</code> for data transfers</strong> — never manual <code>Array()</code> / <code>CuArray()</code> calls</p></li><li><p><strong>Defaults serve the common case</strong>: avoid <code>nothing</code> defaults when a concrete default (like <code>CPU()</code>) covers 80% of usage. Minimize boilerplate for the typical user.</p></li><li><p><strong>Keyword argument names must be consistent</strong> across related types and constructors</p></li><li><p><strong>Always use explicit <code>return</code></strong> in functions longer than one expression</p></li><li><p><strong>One operation per line</strong> as default; break long expressions across lines</p></li></ul><h2 id="Agent-Behavior" tabindex="-1">Agent Behavior <a class="header-anchor" href="#Agent-Behavior" aria-label="Permalink to &quot;Agent Behavior {#Agent-Behavior}&quot;">​</a></h2><ul><li><p>Prioritize type stability and GPU compatibility</p></li><li><p>Follow established patterns in existing code</p></li><li><p>Add tests for new functionality; update exports when adding public API</p></li><li><p>Reference physics equations in comments when implementing dynamics</p></li></ul><h2 id="Further-Reading" tabindex="-1">Further Reading <a class="header-anchor" href="#Further-Reading" aria-label="Permalink to &quot;Further Reading {#Further-Reading}&quot;">​</a></h2><p>Detailed reference docs are in <code>.agents/</code> — read on demand:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Document</th><th style="text-align:right;">Content</th></tr></thead><tbody><tr><td style="text-align:right;"><code>.agents/testing.md</code></td><td style="text-align:right;">Full testing guidelines, running tests, debugging</td></tr><tr><td style="text-align:right;"><code>.agents/documentation.md</code></td><td style="text-align:right;">Building docs, fast builds, doctest details, writing examples</td></tr><tr><td style="text-align:right;"><code>.agents/validation.md</code></td><td style="text-align:right;">Reproducing paper results step-by-step</td></tr></tbody></table><h3 id="Auto-loading-Rules" tabindex="-1">Auto-loading Rules <a class="header-anchor" href="#Auto-loading-Rules" aria-label="Permalink to &quot;Auto-loading Rules {#Auto-loading-Rules}&quot;">​</a></h3><p>Rules in <code>.claude/rules/</code> load automatically when you touch matching files:</p><ul><li><p><code>kernel-rules.md</code> — GPU kernel requirements (src/)</p></li><li><p><code>docstring-rules.md</code> — docstring and jldoctest conventions (src/)</p></li><li><p><code>testing-rules.md</code> — test writing and running (test/)</p></li><li><p><code>docs-rules.md</code> — documentation building and style (docs/)</p></li><li><p><code>examples-rules.md</code> — Literate.jl example conventions (examples/)</p></li></ul><h3 id="Skills-slash-commands" tabindex="-1">Skills (slash commands) <a class="header-anchor" href="#Skills-slash-commands" aria-label="Permalink to &quot;Skills (slash commands) {#Skills-slash-commands}&quot;">​</a></h3><ul><li><p><code>/run-tests</code> — run targeted tests, prioritized by what&#39;s likely to break</p></li><li><p><code>/build-docs</code> — build documentation locally</p></li><li><p><code>/add-feature</code> — checklist for adding new physics/features</p></li><li><p><code>/new-simulation</code> — set up, run, and visualize a new simulation (with or without a reference paper)</p></li><li><p><code>/babysit-ci</code> — monitor CI, auto-fix small issues, pause on bigger problems, retrigger flaky runs</p></li></ul>`,36)])])}const h=n(s,[["render",i]]);export{g as __pageData,h as default};
